contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(other != address(this));
        require(address(this).balance >= amount);

        uint beforeCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeOther = c.balances(other); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint afterCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterOther = c.balances(other); if (__ESBMC_reverted()) return;

        assert(afterCaller == beforeCaller + amount && afterOther >= beforeOther);
    }

    receive() external payable {}
}

