contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount, address other) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(other != address(this));
        vm.assume(address(this).balance >= amount);
        uint256 beforeCaller;
        try c.balances(address(this)) returns (uint256 __r) { beforeCaller = __r; } catch { return; }
        uint256 beforeOther;
        try c.balances(other) returns (uint256 __r) { beforeOther = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
